﻿function Get-MtNativeTestInventory {
    <#
    .SYNOPSIS
    Discovers native tests (Test.<ID>.ps1) under a folder and resolves what their suite adds.

    .DESCRIPTION
    Reads every Test.*.ps1 file statically (Read-MtNativeTest) and applies the nearest suite.json between
    the file and the root: suite tags, Source, Suite, help URL template and RequiresMaester (design
    section 3.6). Adds the derived values (test attribute design, section 2.3): Block and the resolved help
    URL. Tests that share an ID or a function name get a DuplicateId error. A built-in root skips its
    Custom folder.

    A test maps itself to a requirement of a framework with Control = '<framework-key>:<id>' (test attribute
    design, section 6). The frameworks are those the suite.json files declare: the ones shipped with Maester,
    the ones of the suites the tests belong to, and the ones under the folders in -Path and -FrameworkPath
    (Get-MtFrameworkIndex). The first Control that names a requirement gives the test its Benchmark, and the
    Related references of the requirements are added to its Control. Each suite.json and framework file is
    read once. A framework with a problem is a warning and gives no Benchmark; so is a Control that names a
    framework and a requirement its file does not have.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject], [object[]])]
    param(
        # Folders or files to scan.
        [Parameter(Mandatory)]
        [AllowEmptyCollection()]
        [string[]] $Path,

        # The root that suite.json files are searched up to.
        [Parameter()]
        [string] $Root,

        # The tests ship with Maester.
        [Parameter()]
        [switch] $BuiltIn,

        # More folders whose suites declare frameworks a Control can refer to. The folders in -Path are searched
        # already; a caller that passes files gives their folder here.
        [Parameter()]
        [AllowEmptyCollection()]
        [string[]] $FrameworkPath = @()
    )

    $files = foreach ($p in $Path) {
        if (Test-Path -LiteralPath $p -PathType Leaf) { (Resolve-Path -LiteralPath $p).Path }
        elseif (Test-Path -LiteralPath $p -PathType Container) {
            $resolved = (Resolve-Path -LiteralPath $p).Path
            $customPrefix = (Join-Path $resolved 'custom') + [System.IO.Path]::DirectorySeparatorChar
            Get-ChildItem -LiteralPath $resolved -Recurse -File -Filter 'Test.*.ps1' -ErrorAction SilentlyContinue |
                ForEach-Object { $_.FullName } |
                Where-Object { -not ($BuiltIn -and $_.StartsWith($customPrefix, [System.StringComparison]::OrdinalIgnoreCase)) }
        }
    }
    $files = @($files | Sort-Object -Unique)
    if (-not $Root) { $Root = if ($Path.Count -gt 0 -and (Test-Path -LiteralPath $Path[0] -PathType Container)) { (Resolve-Path -LiteralPath $Path[0]).Path } else { $null } }

    $suiteCache = @{}
    $read = foreach ($file in $files) {
        [pscustomobject]@{
            Test  = Read-MtNativeTest -Path $file -BuiltIn:$BuiltIn
            Suite = if ($Root) { Get-MtSuiteManifest -File $file -Root $Root -Cache $suiteCache } else { $null }
        }
    }

    # The frameworks a Control can name: every suite is read before the first test is resolved.
    $frameworkRoots = @($Path | Where-Object { Test-Path -LiteralPath $_ -PathType Container }) + @($FrameworkPath | Where-Object { $_ })
    $loaded = @($read | ForEach-Object { Get-MtLoadedFramework -Suite $_.Suite })
    $index = Get-MtFrameworkIndex -Root $frameworkRoots -Framework $loaded -Cache $suiteCache -BuiltIn:$BuiltIn
    foreach ($problem in $index.Problems) { Write-Warning $problem }

    $tests = @(foreach ($entry in $read) { Complete-MtNativeTest -Test $entry.Test -Suite $entry.Suite -Framework $index -BuiltIn:$BuiltIn })

    # A Control that names a framework and a requirement its file does not have: one warning for each framework.
    foreach ($group in ($index.Unresolved | Group-Object { $_.Framework.Key })) {
        $references = @($group.Group | ForEach-Object { "$($_.Id) ($($_.Reference))" }) -join ', '
        Write-Warning "These tests have a Control that names the framework '$($group.Name)' and a requirement that '$($group.Group[0].Framework.File)' does not have, so it gives them no Benchmark: $references."
    }

    # A shim returns another test's function: ShimOf names that test, so a report can show the two as one setting.
    $byFunction = @{}
    foreach ($t in $tests) { if ($t.FunctionName -and $t.Id -and -not $byFunction.ContainsKey($t.FunctionName)) { $byFunction[$t.FunctionName] = $t.Id } }
    foreach ($t in $tests) {
        $target = if ($t.PSObject.Properties['ShimCommand'] -and $t.ShimCommand -and $byFunction.ContainsKey($t.ShimCommand)) { $byFunction[$t.ShimCommand] } else { $null }
        if ($target -eq $t.Id) { $target = $null }
        $t | Add-Member -NotePropertyName ShimOf -NotePropertyValue $target -Force
    }

    # Duplicate IDs and function names. Neither runs.
    foreach ($group in ($tests | Where-Object Id | Group-Object { $_.Id.ToLowerInvariant() } | Where-Object Count -GT 1)) {
        foreach ($t in $group.Group) {
            $others = ($group.Group | Where-Object { $_.File -ne $t.File } | ForEach-Object { $_.File }) -join ', '
            $t.Errors.Add([pscustomobject]@{ Code = 'DuplicateId'; Message = "Another test has the ID $($t.Id): $others."; Line = $t.Line })
        }
    }
    foreach ($group in ($tests | Where-Object FunctionName | Group-Object { $_.FunctionName.ToLowerInvariant() } | Where-Object Count -GT 1)) {
        foreach ($t in $group.Group) {
            $t.Errors.Add([pscustomobject]@{ Code = 'DuplicateId'; Message = "Another test file defines the function $($t.FunctionName)."; Line = $t.Line })
        }
    }
    $tests
}

function Complete-MtNativeTest {
    <#
    .SYNOPSIS
    Adds Source, Suite, Block, the suite's tags, the help URL and the Benchmark to a test read by Read-MtNativeTest.

    .DESCRIPTION
    Block is kept on the result row for 2.x consumers and for XML test-case names. It is the display name of
    Product when the taxonomy registry knows it, else Product as written, else Feature, else the suite's
    Name, else Custom.

    SuiteTag holds the Tags of the suite.json. Like the test's own Tag they are matched by -Tag and
    -ExcludeTag (Get-MtSelectionTag), but they are not written to a result row: a row's Tag holds the tags
    the test's author wrote.

    Benchmark names the requirement the test implements (test attribute design, section 6): Framework,
    Version, Requirement and the requirement's own facts. It comes from the first Control of the test that
    names a requirement of a framework in -Framework (Resolve-MtTestBenchmark), and is $null when none does.
    Control becomes the test's own values followed by the Related references of the requirements they name,
    each once.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object] $Test,
        [Parameter()] [AllowNull()] [object] $Suite,

        # The frameworks a Control can refer to (Get-MtFrameworkIndex). Without it the test has no Benchmark.
        [Parameter()] [AllowNull()] [object] $Framework,
        [Parameter()] [switch] $BuiltIn
    )

    $source = if ($Suite -and $Suite.Source) { [string]$Suite.Source } elseif ($BuiltIn) { 'Maester' } else { 'Custom' }
    $suiteId = if ($Suite -and $Suite.Id) { [string]$Suite.Id } elseif ($BuiltIn) { 'Maester' } else { 'Custom' }
    $block = if ($Test.Product) { Get-MtProductName -Product $Test.Product }
    elseif ($Test.Feature) { [string]$Test.Feature }
    elseif ($Suite -and $Suite.PSObject.Properties['Name'] -and $Suite.Name) { [string]$Suite.Name }
    else { 'Custom' }

    $suiteTags = [string[]]@($(if ($Suite -and $Suite.PSObject.Properties['Tags']) { $Suite.Tags }) | Where-Object { $_ } | ForEach-Object { [string]$_ } | Select-Object -Unique)

    $helpUrl = $Test.HelpUrl
    if (-not $helpUrl -and $Test.Id) {
        $template = if ($Suite -and $Suite.HelpUrlTemplate) { [string]$Suite.HelpUrlTemplate } elseif ($BuiltIn) { 'https://maester.dev/docs/tests/{Id}' } else { $null }
        if ($template) { $helpUrl = $template.Replace('{Id}', $Test.Id) }
    }

    if ($Suite -and $Suite.RequiresMaester -and -not $Test.RequiresMaester) {
        $Test.RequiresMaester = [string]$Suite.RequiresMaester
        $required = ConvertTo-MtRequiredVersion -Value $Test.RequiresMaester
        if (-not $required) {
            $Test.Errors.Add([pscustomobject]@{ Code = 'InvalidMetadata'; Message = "RequiresMaester in suite.json is '$($Test.RequiresMaester)', which is not a version number, for example 3.0."; Line = 1 })
        } elseif ($required -gt $ExecutionContext.SessionState.Module.Version) {
            $Test.Errors.Add([pscustomobject]@{ Code = 'RequiresNewerMaester'; Message = "The suite requires Maester $($Test.RequiresMaester) or later; this is $($ExecutionContext.SessionState.Module.Version)."; Line = 1 })
        }
    }

    $benchmark = $null
    if ($Framework -and @($Test.Control).Count -gt 0) {
        $resolved = Resolve-MtTestBenchmark -Control $Test.Control -Index $Framework
        $benchmark = $resolved.Benchmark
        if ($resolved.Related.Count -gt 0) { $Test.Control = @(@($Test.Control) + @($resolved.Related) | Where-Object { $_ } | Select-Object -Unique) }
        foreach ($miss in $resolved.Unresolved) { $Framework.Unresolved.Add([pscustomobject]@{ Id = $Test.Id; Reference = $miss.Reference; Framework = $miss.Framework }) }
    }

    $Test | Add-Member -NotePropertyMembers ([ordered]@{
            Source       = $source
            Suite        = $suiteId
            Block        = $block
            SuiteTag     = $suiteTags
            HelpUrl      = $helpUrl
            Format       = 'Native'
            Benchmark    = $benchmark
        }) -Force
    # The skip text for a test that returns $null without saying why, when the suite has its own wording.
    if ($Suite -and $Suite.PSObject.Properties['NoResultReason'] -and $Suite.NoResultReason) {
        $Test | Add-Member -NotePropertyName NoResultReason -NotePropertyValue ([string]$Suite.NoResultReason) -Force
    }
    $Test
}

function Get-MtSelectionTag {
    <#
    .SYNOPSIS
    Returns the tags that -Tag and -ExcludeTag match for a native test (test attribute design, section 5.1).

    .DESCRIPTION
    Own: the tags the test's author wrote and the Tags of its suite.json and, for a test shipped with
    Maester, its own ID. Legacy: for a test shipped with Maester, the tags it carried in Maester 2.x
    (assets/Maester.LegacyTags.json), so that every 2.x tag keeps selecting the tests it selected.

    The legacy tags and the ID are used for selection only. They are never written to a result row.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object] $Test
    )

    param(
        [Parameter()] [AllowNull()] [object] $Instance,
        [Parameter(Mandatory)] [string] $Name
    )

    if ($null -eq $Instance) { return $null }
    if ($Instance -is [System.Collections.IDictionary]) {
        if ($Instance.Contains($Name)) { return $Instance[$Name] }
        return $null
    }
    $property = $Instance.PSObject.Properties[$Name]
    if ($property) { return $property.Value }
    $null
}

function Expand-MtTestFamily {
    <#
    .SYNOPSIS
    Calls a family's InstanceSource and returns the instances to run and the rows for those that do not.

    .DESCRIPTION
    The source returns one object per instance: Id (the suffix; required, unique,
    ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$) and optional Title, Severity, Tag, Fields, Data and attribute values (design section 10; see Get-MtInstanceAttribute).
    A source that throws gives one Error row on the parent ID (InstanceSourceFailed); no instances give
    one Skipped row (NoInstances); an invalid or repeated suffix gives one Error row (InvalidInstanceId).
    Instances that an instance-level ID pattern, -ExcludeTestId or a disabled TestSettings row deselects
    get NotRun rows on their instance IDs.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object] $PlanRow,
        [Parameter()] [AllowNull()] [psmoduleinfo] $Module,
        [Parameter(Mandatory)] [pscustomobject] $RunConfig,
        [Parameter()] [AllowNull()] [pscustomobject] $Selection
    )

    $test = $PlanRow.Test
    $parentRow = {
        param($disposition, $code, $detail)
        $copy = [pscustomobject]@{} ; foreach ($prop in $PlanRow.PSObject.Properties) { $copy | Add-Member -NotePropertyName $prop.Name -NotePropertyValue $prop.Value }
        $copy.Disposition = $disposition; $copy.ReasonCode = $code; $copy.ReasonDetail = $detail
        ConvertTo-MtNativeRow -PlanRow $copy
    }

    # The source runs through the engine, like a test: under a timeout, with a stop request honoured, and
    # with exit or a stray break contained. It runs as the parent test, so Add-MtTestResultDetail
    # -SkippedBecause in it skips the family (for example when the feature the family enumerates is not
    # enabled in the tenant). Its timeout is the family's own: the source gets that long, and then each
    # instance gets that long again.
    $sourceItem = [Maester.Engine.MtWorkItem]::new()
    $sourceItem.Id = $test.Id
    $sourceItem.Command = $test.InstanceSource
    $sourceItem.Title = [string]$test.Title
    $sourceItem.Module = $Module
    $sourceItem.Lane = 'Main'
    if ($PlanRow.TimeoutSeconds -gt 0) { $sourceItem.TimeoutSeconds = $PlanRow.TimeoutSeconds }
    $source = @(Invoke-MtEngineRun -WorkItem $sourceItem -Module $ExecutionContext.SessionState.Module) | Select-Object -First 1
    # The box of what the source wrote with Write-MtTestOutput closes with it.
    Write-MtTestOutput -Complete
    $empty = @{ Instances = @(); PlanRows = @{} }
    switch ([string]$source.Status) {
        'Completed' { $instances = @($source.Output | Where-Object { $null -ne $_ }) }
        'Skipped' { return [pscustomobject]($empty + @{ Rows = @(& $parentRow 'Skipped' 'TestSkipped' $source.Reason) }) }
        'Timeout' {
            return [pscustomobject]($empty + @{ Rows = @(& $parentRow 'Error' 'InstanceSourceFailed' "The instance source $($test.InstanceSource) did not finish within $($PlanRow.TimeoutSeconds) seconds.") })
        }
        default {
            return [pscustomobject]($empty + @{ Rows = @(& $parentRow 'Error' 'InstanceSourceFailed' "The instance source $($test.InstanceSource) failed: $($source.Reason)") })
        }
    }
    if ($instances.Count -eq 0) {
        return [pscustomobject]($empty + @{ Rows = @(& $parentRow 'Skipped' 'NoInstances' 'There is nothing in this tenant for this test to check.') })
    }

    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($i in $instances) {
        $suffix = [string]$i.Id
        # \z, not $: $ also matches before a final newline.
        if ($suffix -notmatch '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}\z' -or -not $seen.Add($suffix)) {
            return [pscustomobject]($empty + @{ Rows = @(& $parentRow 'Error' 'InvalidInstanceId' "The instance source returned an invalid or repeated instance ID '$suffix'.") })
        }
    }

    $run = [System.Collections.Generic.List[object]]::new()
    $rows = [System.Collections.Generic.List[object]]::new()
    $planRows = @{}
    $copyRow = {
        $copy = [pscustomobject]@{}
        foreach ($prop in $PlanRow.PSObject.Properties) { $copy | Add-Member -NotePropertyName $prop.Name -NotePropertyValue $prop.Value }
        $copy
    }
    foreach ($i in $instances) {
        $instanceId = "$($test.Id).$($i.Id)"
        $reason = $null
        if (@($PlanRow.InstancePatterns).Count -gt 0 -and -not (Test-MtIdMatch -Id $instanceId -Pattern $PlanRow.InstancePatterns)) {
            $reason = @('NotSelected', 'Not in the list of test IDs to run.')
        } elseif ($Selection -and (Test-MtIdMatch -Id $instanceId -Pattern $Selection.ExcludeTestId)) {
            $reason = @('ExcludedById', "Excluded by ID.")
        } else {
            $setting = Get-MtTestSetting -RunConfig $RunConfig -Id $instanceId
            if ($setting -and $setting.PSObject.Properties['Enabled'] -and $setting.Enabled -eq $false) {
                $reason = @('DisabledByConfig', $(if ($setting.PSObject.Properties['Reason'] -and $setting.Reason) { [string]$setting.Reason } else { 'Disabled in the Maester config.' }))
            }
        }
        if ($reason) {
            $copy = [pscustomobject]@{}; foreach ($prop in $PlanRow.PSObject.Properties) { $copy | Add-Member -NotePropertyName $prop.Name -NotePropertyValue $prop.Value }
            $copy.Disposition = 'NotRun'; $copy.ReasonCode = $reason[0]; $copy.ReasonDetail = $reason[1]
            $rows.Add((ConvertTo-MtNativeRow -PlanRow $copy -Instance $i))
        } else {
            # A config row for this instance can set its own parameters and timeout. They apply over the
            # family's: a parameter the instance row does not name keeps the family's value.
            $own = if ($RunConfig.TestSettingsHash -and $RunConfig.TestSettingsHash.ContainsKey($instanceId)) { $RunConfig.TestSettingsHash[$instanceId] } else { $null }
            $ownParameters = if ($own -and $own.PSObject.Properties['Parameters']) { $own.Parameters } else { $null }
            $hasTimeout = $own -and $own.PSObject.Properties['TimeoutSeconds'] -and $null -ne $own.TimeoutSeconds
            if ($null -ne $ownParameters -or $hasTimeout) {
                $instanceRow = & $copyRow
                if ($null -ne $ownParameters) {
                    $configValues = @{}
                    $overrideValues = @{}
                    foreach ($e in @($PlanRow.EffectiveParameters)) {
                        if ($e.Source -eq 'Config') { $configValues[$e.Name] = $e.Value }
                        elseif ($e.Source -eq 'Parameter') { $overrideValues[$e.Name] = $e.Value }
                    }
                    if ($ownParameters -is [System.Collections.IDictionary]) { foreach ($k in $ownParameters.Keys) { $configValues[[string]$k] = $ownParameters[$k] } }
                    else { foreach ($prop in $ownParameters.PSObject.Properties) { $configValues[$prop.Name] = $prop.Value } }
                    $binding = ConvertTo-MtTestParameter -Test $test -ConfigValue $configValues -Override $overrideValues
                    $instanceRow.EffectiveParameters = $binding.Effective
                    if ($binding.Error) {
                        $instanceRow.Disposition = 'Error'; $instanceRow.ReasonCode = 'InvalidConfiguration'; $instanceRow.ReasonDetail = $binding.Error
                        $rows.Add((ConvertTo-MtNativeRow -PlanRow $instanceRow -Instance $i))
                        continue
                    }
                    $instanceRow.Parameters = $binding.Bound
                }
                # 0 turns the timeout off for this instance.
                if ($hasTimeout) { $instanceRow.TimeoutSeconds = [int]$own.TimeoutSeconds }
                $planRows[[string]$i.Id] = $instanceRow
            }
            $run.Add($i)
        }
    }
    [pscustomobject]@{ Instances = $run.ToArray(); Rows = $rows.ToArray(); PlanRows = $planRows }
}

function Get-MtNativeTestMarkdown {
    <#
    .SYNOPSIS
    Returns the Description and Result template of a native test from its .md file or the module's bundle.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object] $Test
    )

    $content = $null
    if ($Test.MarkdownPath -and (Test-Path -LiteralPath $Test.MarkdownPath)) {
        $content = Get-Content -LiteralPath $Test.MarkdownPath -Raw
    } elseif ($Test.Id) {
        if ($null -eq $script:__MtNativeMarkdownBundle) {
            $bundleFile = Join-Path $ExecutionContext.SessionState.Module.ModuleBase 'Maester.TestMetadata.json'
            $script:__MtNativeMarkdownBundle = if (Test-Path -LiteralPath $bundleFile) { Get-Content -LiteralPath $bundleFile -Raw | ConvertFrom-Json } else { $false }
        }
        if ($script:__MtNativeMarkdownBundle -and $script:__MtNativeMarkdownBundle.PSObject.Properties[$Test.Id]) {
            $entry = $script:__MtNativeMarkdownBundle.($Test.Id)
            return [pscustomobject]@{ Description = $entry.Description; Result = $entry.Result }
        }
    }
    if (-not $content) { return $null }
    $parts = $content -split '<!--- Results --->', 2
    [pscustomobject]@{ Description = $parts[0]; Result = if ($parts.Count -gt 1) { $parts[1] } else { $null } }
}

function ConvertTo-MtNativeRow {
    <#
    .SYNOPSIS
    Builds the result row of a native test from its plan row and, when it ran, the engine's result.

    .DESCRIPTION
    Applies the test contract (design section 5.2), in this order: -SkippedBecause Error; -Investigate;
    any other skip; an uncaught error; the returned value. The row has every 2.x field (Index is set
    later), the 3.0 fields Source, Suite, Format, ReasonCode, ReasonDetail, ParentId, InstanceId,
    Parameters, Diagnostics and Package, and the test's attributes (test attribute design, section 3): Product (the
    key), RelatedProduct, Feature, Area, ResourceType, UserImpact, ImplementationCost, Mitre, Control,
    Lifecycle, ReplacedBy, Service, License and Permission. An attribute the test does not declare is null
    or an empty list, never left out. Tag holds the tags the author wrote, plus the instance's own.

    Benchmark is the requirement of a published benchmark that the test implements: the first Control of the
    test that names a requirement of a framework file (test attribute design, section 6), or null. Control
    then also holds the Related references of the requirements it names, after the test's own.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory)] [object] $PlanRow,
        [Parameter()] [AllowNull()] [object] $RunResult,
        [Parameter()] [AllowNull()] [object] $Instance,
        [Parameter()] [switch] $ForeignModuleLoaded
    )

    $test = $PlanRow.Test
    $isInstance = $null -ne $Instance
    $id = if ($isInstance) { "$($test.Id).$($Instance.Id)" } else { $test.Id }
    $markdown = Get-MtNativeTestMarkdown -Test $test
    $detail = if ($RunResult -and $__MtSession.TestResultDetail.ContainsKey($id)) { $__MtSession.TestResultDetail[$id] } else { $null }

    # Title: the instance's, else the helper's -TestTitle for a family instance, else the attribute's.
    $title = $test.Title
    if ($isInstance) {
        $instanceTitle = Get-MtInstanceValue -Instance $Instance -Name 'Title'
        if ($instanceTitle) { $title = [string]$instanceTitle }
        elseif ($detail -and $detail.TestTitle) { $title = [string]$detail.TestTitle -replace "^$([regex]::Escape($id)):\s*", '' }
    }

    # Severity: config row (instance, then parent), the instance's, the attribute's, then the helper's.
    $setting = if ($__MtSession.MaesterConfig) { Get-MtTestSetting -RunConfig $__MtSession.MaesterConfig -Id $id -ParentId $(if ($isInstance) { $test.Id } else { $null }) } else { $null }
    $severity = if ($setting -and $setting.PSObject.Properties['Severity'] -and $setting.Severity) { [string]$setting.Severity }
    elseif ($isInstance -and (Get-MtInstanceValue -Instance $Instance -Name 'Severity')) { [string](Get-MtInstanceValue -Instance $Instance -Name 'Severity') }
    elseif ($test.Severity) { [string]$test.Severity }
    elseif ($detail -and $detail.Severity) { [string]$detail.Severity }
    else { '' }

    # Authored tags only: no suite tags, no test ID, no flags.
    $tags = @($test.Tag | Where-Object { $_ })
    $instanceTag = if ($isInstance) { Get-MtInstanceValue -Instance $Instance -Name 'Tag' } else { $null }
    if ($instanceTag) { $tags = @($tags + @($instanceTag) | Select-Object -Unique) }

    $result = $PlanRow.Disposition
    $reasonCode = $PlanRow.ReasonCode
    $reasonDetail = $PlanRow.ReasonDetail
    $errorRecords = @()
    $diagnostics = @()
    $duration = [timespan]::Zero

    if ($RunResult) {
        $duration = $RunResult.Duration
        $diagnostics = @(@($RunResult.Warnings | ForEach-Object { "WARNING: $($_.Message)" }) + @($RunResult.Errors | ForEach-Object { "ERROR: $($_.Exception.Message)" }))
        $status = [string]$RunResult.Status
        $kind = [string]$RunResult.ReturnKind
        $skipCode = if ($detail) { [string]$detail.TestSkipped } else { $null }
        if ($RunResult.TerminatingError) { $errorRecords = @($RunResult.TerminatingError) }

        if ($ForeignModuleLoaded) {
            $result = 'Error'; $reasonCode = 'ForeignModuleLoaded'
            $reasonDetail = 'Another version of Maester was loaded while this test ran, so its result cannot be trusted.'
        } elseif ($skipCode -eq 'Error') {
            $result = 'Error'; $reasonCode = 'TestError'; $reasonDetail = Get-MtFirstLine $detail.SkippedReason
        } elseif ($detail -and $detail.TestInvestigate) {
            $result = 'Investigate'; $reasonCode = $null; $reasonDetail = $null
        } elseif ($status -eq 'Skipped' -or $skipCode) {
            $result = 'Skipped'
            $reasonCode = if ($skipCode -eq 'NotApplicable') { 'NotApplicable' } else { 'TestSkipped' }
            $reasonDetail = if ($detail) { [string]$detail.SkippedReason } else { $RunResult.Reason }
        } elseif ($status -eq 'Error') {
            $result = 'Error'
            $reasonCode = if ($RunResult.IsParameterBindingError) { 'InvalidConfiguration' } else { 'TestError' }
            $reasonDetail = $RunResult.Reason
        } elseif ($status -in 'Aborted', 'Cancelled', 'NotRun') {
            $result = 'Error'; $reasonCode = 'TestError'; $reasonDetail = $RunResult.Reason
        } elseif ($status -eq 'Timeout') {
            $result = 'Error'; $reasonCode = 'Timeout'; $reasonDetail = $RunResult.Reason
        } else {
            switch ($kind) {
                'True' { $result = 'Passed'; $reasonCode = $null; $reasonDetail = $null }
                'False' { $result = 'Failed'; $reasonCode = $null; $reasonDetail = $null }
                'Null' {
                    $result = 'Skipped'; $reasonCode = 'NoResult'
                    $reasonDetail = if ($test.PSObject.Properties['NoResultReason'] -and $test.NoResultReason) { $test.NoResultReason } else { 'The test returned no result.' }
                }
                default {
                    $result = 'Error'; $reasonCode = 'InvalidReturn'
                    $reasonDetail = if ($kind -eq 'Multiple') { 'The test returned more than one value; it must return $true or $false.' } else { "The test returned $($RunResult.ReturnValue.GetType().Name); it must return `$true or `$false." }
                }
            }
        }
        $__MtSession.NativeReturnValue[$id] = $kind
    }

    # Rows the engine produced without a recorded detail still carry the 2.x text fields.
    if (-not $detail) {
        $description = if ($markdown) { $markdown.Description } else { 'This test was not run.' }
        $detail = switch ($result) {
            'NotRun' { @{ TestTitle = $null; TestDescription = $description; TestResult = 'This test was not run.'; TestSkipped = $null; SkippedReason = $null; TestInvestigate = $false; Severity = $null; Service = $null } }
            'Skipped' { @{ TestTitle = $null; TestDescription = $description; TestResult = "Skipped. $reasonDetail"; TestSkipped = $PlanRow.LegacySkipCode; SkippedReason = $reasonDetail; TestInvestigate = $false; Severity = $null; Service = $null } }
            'Error' {
                $errorText = if ($RunResult -and $RunResult.TerminatingError) { ($RunResult.TerminatingError | Out-String).Trim() } else { $reasonDetail }
                $reason = "An error occurred while running the test. ⚠️`n`n" + '```' + "`n`n$errorText`n`n" + '```' + "`n`n"
                @{ TestTitle = $null; TestDescription = $description; TestResult = "Error. $reason"; TestSkipped = $null; SkippedReason = $reason; TestInvestigate = $false; Severity = $null; Service = $null }
            }
            default { $null }
        }
    }
    if ($detail -is [hashtable]) { $detail = [pscustomobject]$detail }

    $file = if ($test.BuiltIn -and $test.File) { ConvertTo-MtRepositoryPath -Path $test.File } else { $test.File }

    $row = [ordered]@{
        Index           = 0
        Id              = $id
        Title           = $title
        Name            = "${id}: $title"
        HelpUrl         = $test.HelpUrl
        Severity        = $severity
        Tag             = $tags
        Result          = $result
        ScriptBlock     = ''
        ScriptBlockFile = $file
        ErrorRecord     = $errorRecords
        Block           = $test.Block
        Product         = $test.Product
        Duration        = $duration.ToString('hh\:mm\:ss\.fff')
        ResultDetail    = $detail
        Source          = $test.Source
        Suite           = $test.Suite
        Format          = 'Native'
        ReasonCode      = $reasonCode
        ReasonDetail    = $reasonDetail
        ParentId        = if ($isInstance -or $test.InstanceSource) { $test.Id } else { $null }
        InstanceId      = if ($isInstance) { $id } else { $null }
        Parameters      = @($PlanRow.EffectiveParameters)
        Diagnostics     = $diagnostics
        # The pack a test comes from (Maester Packs design, section 5.5); null for every other test.
        Package         = if ($test.PSObject.Properties['Package']) { $test.Package } else { $null }
        # Facts a family instance adds about itself, such as the pillar of a Zero Trust Assessment result.
        Fields          = if ($isInstance) { ConvertTo-MtInstanceField (Get-MtInstanceValue -Instance $Instance -Name 'Fields') } else { $null }
        # The test whose function a benchmark shim returns: the two report the same setting.
        ShimOf          = if ($test.PSObject.Properties['ShimOf']) { $test.ShimOf } else { $null }
    }
    $attributes = Get-MtRowAttribute -Test $test
    foreach ($name in $attributes.Keys) { $row[$name] = $attributes[$name] }
    # A family instance can say what it is about when that differs from its family: a Zero Trust Assessment
    # result is about Entra ID, Intune or Exchange, though the family is one test.
    if ($isInstance) {
        $own = Get-MtInstanceAttribute -Instance $Instance -Product $row.Product -RelatedProduct $row.RelatedProduct
        foreach ($name in $own.Keys) { $row[$name] = $own[$name] }
    }
    [pscustomobject]$row
}

function Get-MtInstanceAttribute {
    <#
    .SYNOPSIS
    Returns the attribute values a family instance sets for itself, checked against the taxonomy.

    .DESCRIPTION
    An instance may set Product, RelatedProduct, Feature, Area, UserImpact, ImplementationCost and Mitre. Only
    values the taxonomy knows are returned: a product key or alias (as its key), a feature of that product, an
    area key, Low, Medium or High, and ATT&CK techniques of the pinned release. A value that does not pass is left
    out, so the row keeps its family's value. A Feature is checked against the instance's Product when it sets
    one, else against the family's.

    When the instance moves the row to another product, the family's Feature belongs to the old product: it is
    cleared unless the instance sets a feature of its own, and the new product is taken off the family's
    RelatedProduct. Mitre follows the list rules of a built-in test: None only on its own, at most five
    techniques, no repeats.
    #>
    [CmdletBinding()]
    [OutputType([System.Collections.Specialized.OrderedDictionary])]
    param(
        [Parameter()] [AllowNull()] [object] $Instance,
        # The family's product, used to check a Feature when the instance sets none.
        [Parameter()] [AllowNull()] [AllowEmptyString()] [string] $Product,
        # The family's related products, kept (less the new product) when the instance changes product.
        [Parameter()] [AllowNull()] [string[]] $RelatedProduct
    )

    $values = [ordered]@{}
    if ($null -eq $Instance) { return $values }
    $taxonomy = Get-MtTaxonomy

    $productKey = Resolve-MtProductKey -Name ([string](Get-MtInstanceValue -Instance $Instance -Name 'Product')) -Taxonomy $taxonomy
    $productChanged = $productKey -and $productKey -ne $Product
    if ($productKey) { $values.Product = $productKey; $Product = $productKey }

    $related = @(@(Get-MtInstanceValue -Instance $Instance -Name 'RelatedProduct') | Where-Object { $_ } |
            ForEach-Object { Resolve-MtProductKey -Name ([string]$_) -Taxonomy $taxonomy } | Where-Object { $_ -and $_ -ne $Product } | Select-Object -Unique)
    if ($related.Count) { $values.RelatedProduct = [string[]]$related }
    elseif ($productChanged -and $RelatedProduct -contains $Product) { $values.RelatedProduct = [string[]]@($RelatedProduct | Where-Object { $_ -ne $Product }) }

    $feature = [string](Get-MtInstanceValue -Instance $Instance -Name 'Feature')
    $features = $null
    if ($feature -and $Product -and $taxonomy.Lookup.Feature.TryGetValue($Product, [ref] $features) -and $features.ContainsKey($feature)) {
        $values.Feature = [string]$features[$feature].Key
    } elseif ($productChanged) {
        $values.Feature = $null
    }

    $area = [string](Get-MtInstanceValue -Instance $Instance -Name 'Area')
    if ($area -and $taxonomy.Lookup.Area.ContainsKey($area)) { $values.Area = [string]$taxonomy.Lookup.Area[$area].Key }

    foreach ($name in 'UserImpact', 'ImplementationCost') {
        $value = [string](Get-MtInstanceValue -Instance $Instance -Name $name)
        if ($value -in 'Low', 'Medium', 'High') { $values[$name] = (Get-Culture).TextInfo.ToTitleCase($value.ToLowerInvariant()) }
    }

    $mitre = @(@(Get-MtInstanceValue -Instance $Instance -Name 'Mitre') | Where-Object { $_ } | ForEach-Object { [string]$_ })
    if ($mitre.Count) {
        $techniques = @($mitre | Where-Object { $_ -ne 'None' -and -not (Get-MtAttackTechniqueProblem -Mitre $_) } | Select-Object -Unique)
        if ($techniques.Count) { $values.Mitre = [string[]]@($techniques | Select-Object -First 5) }
        elseif ($mitre -contains 'None') { $values.Mitre = [string[]]@('None') }
    }
    $values
}

function ConvertTo-MtInstanceField {
    <#
    .SYNOPSIS
    Returns the Fields of a family instance as an object of names to strings or string arrays, or $null.

    .DESCRIPTION
    An instance source may return Fields as a hashtable or an object. Only values a report can show are kept:
    a string, a number, a boolean or an array of those, written as text. Anything else, and an empty value,
    is left out, so an instance cannot carry its raw data into the result through Fields.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Position = 0)] [AllowNull()] [object] $Fields
    )

    if ($null -eq $Fields) { return $null }
    $pairs = if ($Fields -is [System.Collections.IDictionary]) { @($Fields.GetEnumerator() | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Key; Value = $_.Value } }) }
    else { @($Fields.PSObject.Properties | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Value = $_.Value } }) }
    $simple = { param($v) $v -is [string] -or $v -is [bool] -or $v -is [int] -or $v -is [long] -or $v -is [double] -or $v -is [decimal] }
    $out = [ordered]@{}
    foreach ($pair in $pairs) {
        if (-not $pair.Name) { continue }
        $value = $pair.Value
        if ($value -is [System.Collections.IEnumerable] -and $value -isnot [string]) {
            $items = @($value | Where-Object { $null -ne $_ -and (& $simple $_) -and "$_" -ne '' } | ForEach-Object { [string]$_ })
            if ($items.Count -gt 0) { $out[$pair.Name] = $items }
        } elseif ($null -ne $value -and (& $simple $value) -and "$value" -ne '') {
            $out[$pair.Name] = [string]$value
        }
    }
    if ($out.Count -eq 0) { return $null }
    [pscustomobject]$out
}

function Get-MtRowAttribute {
    <#
    .SYNOPSIS
    Returns the attribute fields of a result row (test attribute design, section 3) for a native test.

    .DESCRIPTION
    RelatedProduct, Feature, Area, ResourceType, UserImpact, ImplementationCost, Mitre, Control, Lifecycle,
    ReplacedBy, Service, License and Permission, in that order, then Benchmark (test attribute design,
    section 6), which is null unless a Control of the test names a requirement of a framework. Without -Test
    every field is null, which is what a Pester-format row carries.
    #>
    [CmdletBinding()]
    [OutputType([System.Collections.Specialized.OrderedDictionary])]
    param(
        [Parameter()] [AllowNull()] [object] $Test
    )

    $fields = [ordered]@{}
    foreach ($name in 'RelatedProduct', 'Feature', 'Area', 'ResourceType', 'UserImpact', 'ImplementationCost', 'Mitre', 'Control', 'Lifecycle', 'ReplacedBy', 'Service', 'License', 'Permission') {
        if (-not $Test) { $fields[$name] = $null; continue }
        $property = $Test.PSObject.Properties[$name]
        $fields[$name] = if ($name -in 'RelatedProduct', 'Mitre', 'Control', 'Service', 'License', 'Permission') {
            , [string[]]@($(if ($property) { $property.Value }) | Where-Object { $_ })
        } elseif ($property -and $property.Value) { [string]$property.Value } else { $null }
    }
    $benchmark = if ($Test) { $Test.PSObject.Properties['Benchmark'] }
    $fields['Benchmark'] = if ($benchmark -and $benchmark.Value) { $benchmark.Value } else { $null }
    $fields
}

